// Truncating at the boundary rather than trusting upstream. Every adapter owns its own
// platform limits so a factory never has to know them.
const CH = JSON.parse($env.MOS_CHANNELS || '{}').linkedin || {};
const c = $json.payload.content || {};
const fmt = CH.formats?.[$json.payload.format] || CH.formats?.post || {};
let body = c.body || '';
const tags = (c.hashtags || []).slice(0, fmt.hashtags_max ?? 5);
let warn = null;
if (fmt.max_chars && body.length > fmt.max_chars) { body = body.slice(0, fmt.max_chars - 1); warn = 'truncated_to_channel_limit'; }
return [{ json: { body, hashtags: tags, warn, asset_urls: c.asset_urls || [], alt_text: c.alt_text || null, link: c.link || null, first_comment: c.first_comment || null } }];
